begin;
-- Fase 6 — passe de profundidade do módulo 3
update nexora.lessons
set content=((content - (jsonb_array_length(content)-1)) || $json$[{"type":"guided_analysis","title":"Verifique se o SENÃO realmente representa todo o restante","body":"Antes de usar SENÃO, pergunte se o domínio já foi validado. Em uma regra de frete com valor do pedido válido, SENÃO pode significar simplesmente “abaixo do limite”. Mas se `valorPedido` puder estar ausente ou inválido, o mesmo SENÃO passaria a misturar um caso comercial legítimo com erro de entrada.\n\nEssa distinção prepara decisões mais robustas sem abandonar a simplicidade de dois caminhos."},{"type":"mistake","title":"SENÃO genérico demais pode esconder um terceiro estado","body":"Se a regra parece binária apenas porque casos inválidos foram ignorados, a bifurcação está incompleta. Valide pré-condições antes ou crie um tratamento específico. O objetivo não é adicionar ramos desnecessários; é garantir que os dois ramos representem realmente todo o domínio válido."}]$json$::jsonb || jsonb_build_array(content->(jsonb_array_length(content)-1)))
where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=2;
update nexora.lessons
set content=((content - (jsonb_array_length(content)-1)) || $json$[{"type":"comparison","title":"Intuição × cobertura explícita","body":"É fácil olhar para `A && B` e afirmar que entendeu. A tabela-verdade força uma prova: quatro combinações precisam produzir exatamente as quatro saídas esperadas. Quando a regra usa três booleanos, o espaço completo chega a oito combinações.\n\nNem sempre todos os casos precisam virar interface visível, mas a equipe deve saber quais combinações foram deliberadamente cobertas."},{"type":"mistake","title":"Não derive a expectativa a partir do código que está sendo testado","body":"Se você monta a tabela depois de olhar a implementação, corre o risco de copiar o próprio erro para a expectativa. Primeiro derive resultados do requisito; depois compare com o comportamento do código. Assim a tabela funciona como oráculo independente, não como espelho da implementação."}]$json$::jsonb || jsonb_build_array(content->(jsonb_array_length(content)-1)))
where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=3 limit 1) and position=6;
commit;